export function evaluate(c,data){if(!c||!c.field)return true;let v=data[c.field],a=String(v??''),b=String(c.value??'');switch(c.op){case'eq':return a===b;case'neq':return a!==b;case'gt':return a.trim()!==''&&b.trim()!==''&&Number.isFinite(Number(a))&&Number.isFinite(Number(b))&&Number(a)>Number(b);case'lt':return a.trim()!==''&&b.trim()!==''&&Number.isFinite(Number(a))&&Number.isFinite(Number(b))&&Number(a)<Number(b);case'contains':return a.toLowerCase().includes(b.toLowerCase());case'filled':return a.trim()!=='';default:throw Error('Unsupported condition');}}
export function validate(w){if(!w.name.trim())throw Error('Name the workflow');if(!w.documents.length)throw Error('Add a document or web form');if(!w.steps.length)throw Error('Add at least one recipient step');const ids=new Set(w.steps.map(s=>s.id)),names=new Set();for(let f of w.fields){if(!/^[A-Za-z][A-Za-z0-9_]*$/.test(f.key))throw Error('Field keys must begin with a letter and use letters, digits or underscores');if(names.has(f.key))throw Error('Field keys must be unique');names.add(f.key);}const marks=new Map();function visit(id){if(marks.get(id)===1)throw Error('Workflow contains a cycle');if(marks.get(id)===2)return;marks.set(id,1);let s=w.steps.find(s=>s.id===id);for(let p of s.after){if(!ids.has(p))throw Error('A predecessor step is missing');visit(p);}marks.set(id,2);}for(let s of w.steps){if(!s.name.trim())throw Error('Name every step');if(s.condition?.field&&!names.has(s.condition.field))throw Error('A step condition refers to a missing field');visit(s.id);}return true;}
export function interpolate(text,data){return text.replace(/\{\{\s*([A-Za-z][A-Za-z0-9_]*)\s*\}\}/g,(_,key)=>String(data[key]??''));}
export function advance(run){let changed=true;while(changed){changed=false;for(let step of run.definition.steps){if(run.states[step.id]!=='pending')continue;if(!step.after.every(id=>['completed','skipped'].includes(run.states[id])))continue;if(!evaluate(step.condition,run.data)){run.states[step.id]='skipped';run.events.push({at:new Date().toISOString(),action:'condition.skipped',step:step.name});changed=true;continue;}if(step.type==='bot'){if(step.bot==='tag'&&step.value)run.tags.push(step.value);if(step.bot==='prefill'&&step.field)run.data[step.field]=step.value;run.states[step.id]='completed';run.events.push({at:new Date().toISOString(),action:'local_bot.completed',step:step.name});changed=true;}else{run.states[step.id]='ready';run.events.push({at:new Date().toISOString(),action:'step.ready',step:step.name});changed=true;}}}if(Object.values(run.states).every(s=>['completed','skipped'].includes(s)))run.status='completed';return run;}
export function createRun(w,data){validate(w);const frozen=structuredClone(w);return advance({id:crypto.randomUUID(),name:w.name,definition:frozen,version:w.version,createdAt:new Date().toISOString(),status:'in_progress',data:{...data},states:Object.fromEntries(w.steps.map(s=>[s.id,'pending'])),tags:[],events:[{at:new Date().toISOString(),action:'local_run.started',step:''}]});}
export function complete(run,id,decision='complete'){if(run.status!=='in_progress'||run.states[id]!=='ready')throw Error('This step is not available');const step=run.definition.steps.find(s=>s.id===id);if(decision==='decline'){run.states[id]='declined';run.status='declined';run.events.push({at:new Date().toISOString(),action:'step.declined',step:step.name});return run;}run.states[id]='completed';run.events.push({at:new Date().toISOString(),action:'local_user.completed',step:step.name});return advance(run);}
